  p_PrefillFallbackText_a1dc60146c54 TEXT;
  p_ModelConfiguration_a1dc60146c54 TEXT;
BEGIN
  p_ID_a1dc60146c54 := 'F85E5A1F-2793-49F2-A850-F6B4B2FCEFBC';
  p_Name_a1dc60146c54 := 'Qwen 3.8 27B';
  p_Description_a1dc60146c54 := 'Alibaba''s dense 27B-parameter update to the Qwen 3.6 27B open-weights model, and the model Groq names as the direct replacement for `qwen/qwen3.6-27b` on its deprecation schedule (qwen3.6-27b shut down 2026-09-14). Carried here for the Groq route: ~131K-token context with up to 16,384 output tokens, tool calling, structured outputs and vision input. Served on Groq''s Preview tier, which Groq documents as intended for evaluation and subject to discontinuation at short notice, so the route is seeded at Preview and is never selected automatically. Reported Groq pricing is $0.80/1M input and $4.00/1M output (against $0.60/$3.00 for qwen3.6-27b), but that figure comes only from third-party aggregators — Groq''s own pricing page was unreachable when this record was added on 2026-11-02 — so no cost row is seeded. Add one once the rate is confirmed first-party.';
  p_AIModelTypeID_a1dc60146c54 := (
    SELECT
      "ID"
    FROM
      __mj."AIModelType"
    WHERE
      LOWER("Name") = LOWER('LLM')
  );
  p_PowerRank_a1dc60146c54 := 15;
  p_IsActive_a1dc60146c54 := TRUE;
  p_SpeedRank_a1dc60146c54 := 8;
  p_CostRank_a1dc60146c54 := 3;
  p_InheritTypeModalities_a1dc60146c54 := TRUE;
  p_PriorVersionID_a1dc60146c54 := (
    SELECT
      "ID"
    FROM
